from fractions import Fraction

n = int(input())
for problem in range(n):
    p = int(input())
    b = int(input())
    print(f"f(x) = x^3 + {p}x, find (f^-1)'({b})")
    a = 0
    for guess in range(-10, 11):
        if guess**3 + p * guess == b:
            a = guess
    slope = 3 * a**2 + p
    print(f"  a = {a}, f'(a) = {slope}")
    if slope == 0:
        print("  vertical tangent")
    else:
        print(f"  (f^-1)'({b}) = {Fraction(1, slope)}")
